import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"反略奪主義核心論綱","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0004-反掠夺主义核心论纲.md","filePath":"ja/0004-反掠夺主义核心论纲.md"}'),l={name:"ja/0004-反掠夺主义核心论纲.md"};function o(i,t,h,n,s,_){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="反略奪主義核心論綱" tabindex="-1">反略奪主義核心論綱 <a class="header-anchor" href="#反略奪主義核心論綱" aria-label="Permalink to &quot;反略奪主義核心論綱&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>04</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>反略奪、略奪批判、共生代替、倫理的限界、体系革命</td></tr></tbody></table><h2 id="第一節-略奪主義の定義と表現" tabindex="-1">第一節 略奪主義の定義と表現 <a class="header-anchor" href="#第一節-略奪主義の定義と表現" aria-label="Permalink to &quot;第一節 略奪主義の定義と表現&quot;">​</a></h2><p>略奪主義とは、他の生命または位面の本源、エネルギー、気運、資源を無償で占有、吞噬、搾取することを核心的手段とし、自身または自集団の進化を目標とする宇宙観と修練体系を指す。略奪主義は特定の修練功法ではなく、修練理念、社会制度、文明関係に貫徹する根本的立場である。</p><p>衡元宙の歴史において、略奪主義は以下の主要な形態で表現された：</p><table tabindex="0"><thead><tr><th>形態</th><th>表現</th><th>危害</th></tr></thead><tbody><tr><td>エネルギー略奪</td><td>他の生命の修練エネルギーまたは本源を直接吞噬する</td><td>略奪された者の死亡または修練の完全な廃絶、宇宙エネルギー循環の寸断</td></tr><tr><td>気運略奪</td><td>秘術を通じて他人または種族の気運を窃取する</td><td>略奪された者の運命の崩壊、種族の衰退</td></tr><tr><td>法门独占</td><td>少数の宗派が修練法门を独占し、伝授権を忠誠と資源と交換する</td><td>階層の固定化、下層衆生の進化経路の喪失</td></tr><tr><td>位面植民</td><td>高位位面が低位位面を征服し、その資源と人口を略奪する</td><td>位面膜の損傷、位面生態の崩壊</td></tr><tr><td>精神奴隷</td><td>霊魂制御手段を通じて他の生命を修練道具に変える</td><td>奴隷化された者の自由意志の剥奪、生命尊厳の侵害</td></tr><tr><td>資源涸渇</td><td>惑星または位面の資源を無節制に採掘する</td><td>生態絶滅、宇宙エントロピー増大の加速</td></tr></tbody></table><h2 id="第二節-略奪主義の根本的誤り" tabindex="-1">第二節 略奪主義の根本的誤り <a class="header-anchor" href="#第二節-略奪主義の根本的誤り" aria-label="Permalink to &quot;第二節 略奪主義の根本的誤り&quot;">​</a></h2><p>反略奪主義は、略奪主義には根本的に三重の誤りがあると考える：</p><h3 id="_2-1-宇宙観の誤り-宇宙を有限な狩場と見なす" tabindex="-1">2.1 宇宙観の誤り：宇宙を有限な狩場と見なす <a class="header-anchor" href="#_2-1-宇宙観の誤り-宇宙を有限な狩場と見なす" aria-label="Permalink to &quot;2.1 宇宙観の誤り：宇宙を有限な狩場と見なす&quot;">​</a></h3><p>略奪主義の宇宙観は宇宙を資源有限の狩場と見なし、進化は必然的にゼロサムゲームであり、強者の進歩は必然的に弱者の犠牲を代償とすると考える。この宇宙観は宇宙自体の「進化可能性」を無視している——宇宙は静的な資源容器ではなく、秩序ある共生網を通じて全体的な昇維を実現できる生命体である。略奪者が弱者を吞噬するとき、彼らは弱者のエネルギーだけでなく、宇宙全体の進化潜在能力も消費している。</p><h3 id="_2-2-倫理の誤り-強者の進化権を弱者の生存権の上に置く" tabindex="-1">2.2 倫理の誤り：強者の進化権を弱者の生存権の上に置く <a class="header-anchor" href="#_2-2-倫理の誤り-強者の進化権を弱者の生存権の上に置く" aria-label="Permalink to &quot;2.2 倫理の誤り：強者の進化権を弱者の生存権の上に置く&quot;">​</a></h3><p>略奪主義は「弱肉強食」を自然法則として受け入れ、強者には弱者を吞噬する権利さらには義務さえあると考える。この倫理観は自然選択と道徳選択を混同している。自然界において、弱肉強食は無意識の生態法則である；しかし意識ある修練文明において、強者には選択する能力があり、したがって選択の責任を負うべきである。「天道」を口実とする略奪は、本質的に強者が自身の貪欲を宇宙法則として包装することである。</p><h3 id="_2-3-効率の誤り-略奪が最速の進化経路であると信じる" tabindex="-1">2.3 効率の誤り：略奪が最速の進化経路であると信じる <a class="header-anchor" href="#_2-3-効率の誤り-略奪が最速の進化経路であると信じる" aria-label="Permalink to &quot;2.3 効率の誤り：略奪が最速の進化経路であると信じる&quot;">​</a></h3><p>略奪主義は略奪が最速かつ最高効率の進化経路であると主張する。しかし長期的に見ると、略奪式進化には深刻な「効率の天井」が存在する：第一に、略奪によって得られたエネルギーにはしばしば原主の意志残痕が付着しており、精錬と純化に多大な労力を費やす必要がある；第二に、略奪行為は略奪された者とその関連集団の反抗を引き起こし、修練の外部コストを増大させる；第三に、長期的な略奪への依存は修練者自身の本源進化能力の退化を引き起こし、略奪対象を失うと停滞に陥る；第四に、略奪式修練者は至高境界を突破する際にしばしば「本源不純」のボトルネックに直面し、真に宇宙本源に触れることが困難である。</p><h2 id="第三節-反略奪主義の核心命題" tabindex="-1">第三節 反略奪主義の核心命題 <a class="header-anchor" href="#第三節-反略奪主義の核心命題" aria-label="Permalink to &quot;第三節 反略奪主義の核心命題&quot;">​</a></h2><p>反略奪主義は単にすべての競争と差異を否定するのではなく、以下の核心命題を提出する：</p><ol><li><strong>進化は非ゼロサムでありうる</strong>：共生循環と錨点網を通じて、万族の進化は相乗効果を生み出し、部分の和を超える全体的な進化効能を実現できる。</li><li><strong>競争は創造的であるべきで、破壊的であるべきではない</strong>：反略奪主義は良性の競争に反対しないが、競争の方式は自身の創造能力を高めることであるべきで、相手を消滅させる略奪能力であるべきではない。</li><li><strong>強者の責任は権利より大きい</strong>：修練者の境界が高いほど、共生網に対する責任が大きく、略奪の権利が大きいのではない。高級修練者には初級修練者を指導し、錨点の安定を維持し、文明の安全を保護する義務がある。</li><li><strong>資源は創造によって増加すべきで、略奪によって分配すべきではない</strong>：共生文明の核心的な考え方はケーキを大きくすることであり、ケーキを切り分けることではない；技術進歩と法則応用を通じて不断に新しい修練資源を創造する。</li><li><strong>反略奪は平均主義ではない</strong>：反略奪主義が反対するのは労せずして得る略奪であり、多労多得の差異ではない。共生文明は進化成果の差異を認めるが、差異は必ず自身の努力と貢献に由来しなければならないと主張する。</li></ol><h2 id="第四節-反略奪主義の制度的保障" tabindex="-1">第四節 反略奪主義の制度的保障 <a class="header-anchor" href="#第四節-反略奪主義の制度的保障" aria-label="Permalink to &quot;第四節 反略奪主義の制度的保障&quot;">​</a></h2><p>反略奪主義は単なる理論的主張ではなく、一連の制度的保障を有する：</p><ul><li><strong>法律保障</strong>：共生憲法及び独占禁止法は略奪行為を明確に禁止し、錨点法院は略奪案件に対し管轄権を有する</li><li><strong>機制保障</strong>：聯産承包機制は資源分配が暴力ではなく貢献に基づくことを確保し、錨点網は異常なエネルギー流動を監視する</li><li><strong>体系保障</strong>：三百套の本源修練体系はすべて共生循環原理に基づいており、略奪式法门は存在しない</li><li><strong>教育保障</strong>：共生教育体系は反略奪倫理を必修科目とし、根源から略奪思想を根絶する</li><li><strong>監督保障</strong>：万族共和議会は反略奪委員会を設置し、専門的に略奪行為を監督・調査する</li></ul><h2 id="第五節-残余略奪勢力に対する政策" tabindex="-1">第五節 残余略奪勢力に対する政策 <a class="header-anchor" href="#第五節-残余略奪勢力に対する政策" aria-label="Permalink to &quot;第五節 残余略奪勢力に対する政策&quot;">​</a></h2><p>宇宙に依然として存在する残余略奪勢力に対し、共生文明は「隔離、転化、制裁」の三策を併用する方針を採用する：まだ深刻な危害を引き起こしていない略奪者に対しては、倫理教育と体系転化を行い、共生体系に加入するよう導く；転化を拒否し共生秩序に持続的に危害を加える略奪者に対しては、位面隔離と修練制限を実施する；重大な災害を引き起こした略奪者に対しては、法に基づき制裁を行う。共生文明は略奪によって反略奪することを主張せず、すべての制裁は錨点法院の公正な審判を経なければならない。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>反略奪主義は錨点共生文明の理論的基石の一つである。それは旧時代の略奪体系に対する批判であるだけでなく、共生進化の可能性に対する積極的な構築でもある。反略奪主義の究極的目標は強者を消滅させることではなく、強者の力を万族の共同進化に奉仕させることである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (錨点共生文明宣言)</li><li>03-共生文明宪章 (共生文明憲章)</li><li>19-修炼伦理与边界 (修練倫理と境界)</li></ul>',26)])])}const p=a(l,[["render",o]]);export{b as __pageData,p as default};
